css:
.ci-header { text-align: center; margin-bottom: 15px; }
.ci-party { width: 100%; border-collapse: collapse; margin: 10px 0; }
.ci-party td { vertical-align: top; padding: 6px; border: 1px solid #ddd; }
.ci-table { width: 100%; border-collapse: collapse; margin-top: 10px; font-size: 0.9em; }
.ci-table th, .ci-table td { border: 1px solid #ccc; padding: 6px 8px; }
.ci-table th { background: #f5f5f5; }
.ci-totals { width: 60%; margin-left: auto; margin-top: 15px; }
.ci-totals td { padding: 4px 8px; }
.ci-totals .grand { font-weight: bold; border-top: 2px solid #333; font-size: 1.1em; }
.words { margin-top: 10px; font-size: 0.85em; }
.ar { direction: rtl; }
.ar-line { direction: rtl; color: #444; font-size: 0.9em; }
.sign { margin-top: 40px; width: 100%; }
.sign td { border-top: 1px solid #333; padding-top: 5px; font-size: 0.85em; }
